<script setup lang="ts">
import {ref,watch} from 'vue';import {useLab} from '../store';import type {SourceRange} from '../generated/SourceRange';import SqlEditor from '../components/SqlEditor.vue';import {type AlgebraResult,exportText} from '../api';import TraceView from '../components/TraceView.vue';const props=defineProps<{theme:string}>();const lab=useLab();const editor=ref<InstanceType<typeof SqlEditor>>();function highlight(range:SourceRange|null){editor.value?.highlight(optimized.value?null:range)};const result=ref<AlgebraResult>();const optimized=ref(false);watch(()=>lab.epoch,()=>result.value=undefined);const examples=[['选择与投影','project{Sno,Sname}(select{Sage >= 18}(Student))'],['自然连接与下推','project{Sno,Sname,Grade}(select{Cno = \'1\'}(join(Student,SC)))'],['分组聚合','group{Sdept;AVG(Sage) AS average_age}(Student)'],['集合差','diff(project{Sno}(Student),project{Sno}(SC))'],['关系除法','divide(project{Sno,Cno}(SC),project{Cno}(Course))']];
async function run(){result.value=undefined;await editor.value?.source(true);const r=await lab.run<AlgebraResult>('algebra','algebra',{expression:lab.workspace!.algebra,optimize:true});if(r){result.value=r;lab.log('关系代数计算完成，优化前后结果已核对')}}
async function report(){if(result.value)await exportText(`# 关系代数实验\n\n集合语义 · SQLite 教学工作区\n\n\`\`\`\n${result.value.expression}\n\`\`\`\n\n## 优化\n\n${result.value.rules.join('\n\n')}\n\n\`\`\`\n${result.value.optimized}\n\`\`\`\n\n等价校验：${result.value.equivalent}\n\n${result.value.trace.steps.map(s=>`## ${s.title}\n\n${s.explanation}\n\n输出：${JSON.stringify(s.table)}`).join('\n\n')}`,'关系代数实验.md');}
</script>
<template><div class="lab-page"><header class="page-heading"><div><span class="eyebrow">RELATIONAL ALGEBRA</span><h1>把查询写成关系运算</h1><p>独立表达式采用集合语义；输入来自当前 SQLite 工作区。</p></div><button @click="report().catch(lab.fail)" :disabled="!result">导出报告 ↗</button></header><div class="algebra-input"><select aria-label="代数示例" @change="lab.workspace!.algebra=($event.target as HTMLSelectElement).value;lab.touch()"><option value="">选择一个例子…</option><option v-for="[label,expression] in examples" :key="label" :value="expression">{{label}}</option></select><div v-if="lab.workspace" class="algebra-code"><SqlEditor ref="editor" id="algebra" :theme="props.theme" v-model="lab.workspace.algebra" :schema="lab.schema" language="plaintext" @update:model-value="lab.touch()" @run="run"/></div><button class="primary" data-testid="algebra-run" :disabled="!!lab.jobs.algebra" @click="run">▶ 运行并优化</button></div><details class="syntax-card"><summary>运算语法与集合语义</summary><div class="syntax-grid"><code>select{条件}(R)</code><span>σ 选择：保留条件为 TRUE 的行</span><code>project{列,…}(R)</code><span>π 投影：选列并去重</span><code>rename{别名}(R)</code><span>ρ 重命名：后续使用该别名限定列</span><code>join{L.列=R.列}(R,S)</code><span>θ 连接；无参数 join(R,S) 是自然连接</span><code>leftjoin / rightjoin / fulljoin</code><span>外连接，参数方式与 join 相同</span><code>union / intersect / diff / product</code><span>∪ / ∩ / − / ×，每次输入两个关系</span><code>divide(R,S)</code><span>÷ 除法：关联 S 中全部元组的候选</span><code>group{键;聚合}(R)</code><span>γ 分组，支持 COUNT、SUM、AVG、MIN、MAX</span></div></details><template v-if="result"><div class="comparison-bar"><button :class="{active:!optimized}" @click="optimized=false">原表达式</button><span>→</span><button :class="{active:optimized}" @click="optimized=true">优化后</button><span class="success">✓ 当前数据结果等价</span><span>中间记录 {{result.trace.steps.reduce((n,s)=>n+s.table.rows.length,0)}} → {{(result.optimized_trace??result.trace).steps.reduce((n,s)=>n+s.table.rows.length,0)}}</span><span v-if="!result.rules.length" class="muted">没有满足前提的下推规则</span></div><div v-if="result.rules.length" class="notice"><p v-for="rule in result.rules" :key="rule">{{rule}}</p><code>{{result.optimized}}</code></div><TraceView :trace="optimized&&result.optimized_trace?result.optimized_trace:result.trace" @highlight="highlight"/></template><div v-else class="empty large">σ · π · ⋈ · ÷<p>选择示例或输入表达式，查看每个运算的真实中间表。</p></div></div></template>
